const regions = ["All", "US", "Europe", "India", "Global"] as const;
const roleFamilies = ["All roles", "Core FDE", "Applied AI / ML", "Data Engineering", "Solutions / Implementation", "Deployment Strategy", "Field Architecture", "Leadership", "Early Career"] as const;

function postedTimestamp(posted: string) {
  if (posted === "Current" || posted === "Live" || posted === "Evergreen") return Infinity;
  // Range labels ("28 Jul – 3 Aug 2026") sort by their later (fresher) bound.
  const rangeEnd = posted.split("–").pop()?.trim() ?? posted;
  const parsed = Date.parse(rangeEnd);
  return Number.isNaN(parsed) ? -Infinity : parsed;
}

function roleFamily(job: Job) {
  const title = job.title.toLowerCase();
  if (/intern|junior|associate|entry/.test(title) || /^(entry|junior)/i.test(job.level)) return "Early Career";
  if (/director|manager|leader|lead\b|head|executive|chief|cto|svp|vice president/.test(title)) return "Leadership";
  if (/strategist|strategy|product owner|technical deployment/.test(title)) return "Deployment Strategy";
  if (/architect/.test(title)) return "Field Architecture";
  if (/data|analytics/.test(title)) return "Data Engineering";
  if (/ai|machine learning|\bml\b|genai|agentic|agents/.test(title)) return "Applied AI / ML";
  if (/solution|implementation|customer engineer|field engineer/.test(title)) return "Solutions / Implementation";
  return "Core FDE";
}

export default function Home() {
  const [region, setRegion] = useState<(typeof regions)[number]>("All");
  const [family, setFamily] = useState<(typeof roleFamilies)[number]>("All roles");
  const [query, setQuery] = useState("");
  const [onlySalary, setOnlySalary] = useState(false);
  const visible = useMemo(() => jobs.filter((job) => {
    const regionMatch = region === "All" || job.region === region;
    const familyMatch = family === "All roles" || roleFamily(job) === family;
    const haystack = `${job.company} ${job.title} ${roleFamily(job)} ${job.lane} ${job.signals.join(" ")}`.toLowerCase();
    return regionMatch && familyMatch && (!onlySalary || Boolean(job.salary)) && haystack.includes(query.toLowerCase());
  }).sort((a, b) => postedTimestamp(b.posted) - postedTimestamp(a.posted)), [region, family, query, onlySalary]);

  return <main>
    <div className="wrap">
      <header className="hero">
        <a className="eyebrow bootcamp-link" href="https://maven.com/boring-bot/ai-system-design" target="_blank" rel="noreferrer">GUIDED ASSET FOR THE AI SYSTEM DESIGN BOOTCAMP ↗</a>
        <h1>Forward Deployed<br/><span>Engineer Jobs.</span></h1>
        <p className="dek">Remote and remote-eligible roles across the US, Europe, and India.</p>
        <div className="hero-meta"><span>{jobs.length} current roles</span><span>US · Europe · India</span><span>Updated 10 Aug 2026</span></div>
        <div className="rule" />
        <details className="sourcing">
          <summary>How we gather these listings</summary>
          <div className="sourcing-body">
            <p>Roles are pulled from two specialist boards — <a href="https://www.fwddeploy.com/s/remote-jobs" target="_blank" rel="noreferrer">FWDDeploy.com</a> and <a href="https://deployaijobs.com/jobs" target="_blank" rel="noreferrer">DeployAI Jobs</a> — plus a handful of direct employer career pages, Indeed, and Ashby. Each candidate is checked against a few criteria before it&apos;s included: the work is explicitly forward-deployed or customer-embedded (not just advisory), it has a clear remote or geographic eligibility, and it isn&apos;t an obvious duplicate posting.</p>
            <p>The board is refreshed by re-crawling those sources and adding anything new since the last pass — most recently on 10 Aug 2026, covering roles posted between 28 Jul and 10 Aug 2026. Dates come straight from each source; where a source only reports an approximate age (e.g. &ldquo;about a week ago&rdquo; instead of an exact day), the listing shows a date range rather than a guessed exact date.</p>
            <p>Always confirm a role is still open before applying.</p>
          </div>
        </details>
      </header>

      <section id="roles">
        <span className="kicker">OPEN ROLES</span><h2>Find your next FDE role.</h2>
        <p className="sub">Filter by hiring region, skills, company, or published compensation.</p>
        <div className="toolbar">
          <div className="tabs" role="group" aria-label="Filter by region">{regions.map(r => <button key={r} className={region === r ? "active" : ""} onClick={() => setRegion(r)}>{r}</button>)}</div>
          <label className="search"><span>⌕</span><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search skill, company, lane…" aria-label="Search roles"/></label>
          <label className="check"><input type="checkbox" checked={onlySalary} onChange={e=>setOnlySalary(e.target.checked)}/><span/> Pay shown</label>
        </div>
        <div className="family-chips" role="group" aria-label="Filter by role family">
          {roleFamilies.map(item => <button key={item} className={family === item ? "active" : ""} aria-pressed={family === item} onClick={() => setFamily(item)}>{item}</button>)}
        </div>
        <div className="count">SHOWING {visible.length} OF {jobs.length} ROLES</div>
        <div className="jobs">{visible.map(job => <article className={`job ${job.featured ? "featured" : ""}`} key={`${job.url}-${job.company}-${job.title}-${job.location}`}>
          <div className="job-top"><div className="logo">{job.company.slice(0,2).toUpperCase()}</div><div className="job-title"><div className="company">{job.company}{job.featured && <span className="pick">EDITOR’S PICK</span>}</div><h3>{job.title}</h3></div><a className="apply" href={job.url} target="_blank" rel="noreferrer" aria-label={`View ${job.title} at ${job.company}`}>View role ↗</a></div>
          <div className="facts"><span>◎ {job.location}</span><span>◈ {job.level}</span>{job.salary && <span className="salary">{job.salary}</span>}<span className="posted">{job.posted}</span></div>
          <div className="tags"><span className="role-family">{roleFamily(job)}</span><span className="lane">{job.lane}</span>{job.signals.map(s=><span key={s}>{s}</span>)}</div>
        </article>)}</div>
        {visible.length === 0 && <div className="empty">No roles match this lens. Try a broader region or search.</div>}
      </section>
      <footer><div><b>FDE JOB BOARD</b><a href="https://maven.com/boring-bot/ai-system-design" target="_blank" rel="noreferrer">A guided asset for the AI System Design bootcamp ↗</a></div><p>Updated 10 Aug 2026 using employer pages, FWDDeploy and DeployAI Jobs. Confirm eligibility before applying.</p></footer>
    </div>
  </main>;
}
